 3→/**
 4→ * Generates a dedup key for a candidate result.
 5→ * Uses candidate_name + candidate_email (normalized) for matching.
 6→ * Falls back to filename if no candidate info available.
 7→ */
 8→function getCandidateKey(r: Result): string {
 9→  const name = (r.candidate_name || "").trim().toLowerCase();
10→  const email = (r.candidate_email || "").trim().toLowerCase();
11→
12→  // If we have email, it's the strongest identifier
13→  if (email) return `email:${email}`;
14→  // If we have a name, use it (handles "ALOK SINGH" case from screenshot)
15→  if (name && name !== "unknown") return `name:${name}`;
16→  // Fallback to filename (no dedup possible)
17→  return `file:${r.resume_id}`;
18→}
