20→/**
21→ * Detects duplicate candidates in results.
22→ * Returns a Set of resume_ids that are duplicates (lower-scoring copies).
23→ * The highest-scoring entry for each candidate is NOT marked as duplicate.
24→ */
25→export function findDuplicateResumeIds(results: Result[]): Set<string> {
26→  const candidateGroups = new Map<string, Result[]>();
27→
28→  for (const r of results) {
29→    if (r.pending) continue;
30→    const key = getCandidateKey(r);
31→    // Only group by candidate info keys, not file-based fallbacks
32→    if (key.startsWith("file:")) continue;
33→    const group = candidateGroups.get(key) || [];
34→    group.push(r);
35→    candidateGroups.set(key, group);
36→  }
37→
38→  const duplicateIds = new Set<string>();
39→  for (const [, group] of candidateGroups) {
40→    if (group.length <= 1) continue;
41→    // Sort by score descending — first entry is the "original", rest are duplicates
42→    group.sort((a, b) => b.overall_score - a.overall_score);
43→    for (let i = 1; i < group.length; i++) {
44→      duplicateIds.add(group[i].resume_id);
45→    }
46→  }
47→
48→  return duplicateIds;
49→}
